  const partial = recordPayment(issued, { amount: 20000, date: '2026-10-05' }).value;
  const text = renderInvoiceText(partial);

  assert.match(text, /discount:/);
  assert.match(text, /Voucher:/);
  assert.match(text, /Due:/);
  assert.match(text, /Paid:/);
  assert.match(text, /VAT:/);

  const lines = text.split('\n');
  const discountLineIdx = lines.findIndex(l => l.includes('discount:'));
  const vatLineIdx = lines.findIndex(l => l.startsWith('VAT:'));
  const voucherLineIdx = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalLineIdx = lines.findIndex(l => l.startsWith('Total:'));
  const dueLineIdx = lines.findIndex(l => l.startsWith('Due:'));
  const paidLineIdx = lines.findIndex(l => l.startsWith('Paid:'));

  assert.equal(discountLineIdx < vatLineIdx, true);
  assert.equal(vatLineIdx < voucherLineIdx, true);
  assert.equal(voucherLineIdx < totalLineIdx, true);
  assert.equal(totalLineIdx < dueLineIdx, true);
  assert.equal(dueLineIdx < paidLineIdx, true);
});

