import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { getCustomer } from './customers.js';
import { totalPaid, balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<any>, terms?: string, dueDate?: string, payments?: Array<any>, voucher?: any }} invoice
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Second line: customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;
  lines.push(customerName);

  // One line per invoice line
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const lineParts = [
      line.qty,
      '×',
      line.name,
      '@',
      formatEuros(line.unitPrice),
      '=',
      formatEuros(total),
    ];
    let lineStr = lineParts.join(' ');
    if (discount > 0) {
      lineStr += ` (discount: ${formatEuros(discount)})`;
    }
    lines.push(lineStr);
  }

  // VAT line (if any VAT applies)
  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher line (if any)
  if (totals.voucher > 0) {
    lines.push(`Voucher: ${formatEuros(totals.voucher)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date line (if invoice has a due date)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid line (if invoice has payments)
  const paid = totalPaid(invoice);
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}
